/* Portrait point layout matching the user-supplied visual reference.
   Source: https://vadimcarazan.com/data/cosmos.json (portrait coordinates only).
   Rendered with BlueFluteX's own thumbnail collection. */
((root)=>{
  "use strict";
  const binary=atob("");
  const points=new Float32Array(binary.length/2);
  for(let i=0;i<points.length;i++) points[i]=(binary.charCodeAt(i*2)+binary.charCodeAt(i*2+1)*256)/(i%4<2?100:1000);
  const portrait={cols:110,rows:157,cell:[0.84926,0.63694],points};
  root.BlueFlutePortrait=portrait;
  if(typeof module!=="undefined") module.exports=portrait;
})(typeof window==="undefined"?globalThis:window);
